function getSalesforceEinsteinTranslation(key, lang) {
    if (salesforceeinsteinTranslations[lang] && salesforceeinsteinTranslations[lang][key]) {
        return salesforceeinsteinTranslations[lang][key];
    }
    if (salesforceeinsteinTranslations.en && salesforceeinsteinTranslations.en[key]) {
        return salesforceeinsteinTranslations.en[key];
    }
    return null;
}

function applySalesforceEinsteinTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.salesforce-einstein.')) {
            const translation = getSalesforceEinsteinTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applySalesforceEinsteinTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applySalesforceEinsteinTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applySalesforceEinsteinTranslations(currentLang);
}


